use super::*;
use crate::config::{Agent, Effort};
use std::fs;
use std::path::Path;

const NOTE: &str =
    "DeepSeek variant of worker on deepseek-flash, billed to the DeepSeek API credit.";
const MARKER: &str = "# Generated by vicarius from worker.md; edits are overwritten on sync.";
const WORKER: &str =
    "---\nname: worker\ndescription: Does work.\nmodel: claude-haiku-5-5\n---\nBody line.\n";
const SENIOR_MARKER: &str =
    "# Generated by vicarius from senior-worker.md; edits are overwritten on sync.";
const SENIOR_WORKER: &str = r##"---
name: senior-worker
description: "Second line after worker. Use only when worker handed the task back or stopped without a passing check, or when the change itself is concurrency or security-sensitive code (locking, async cancellation, auth, sandboxing, shell quoting). Everything else goes to worker first, including large, multi-module, design-heavy or unclear tasks: split them into worker briefs and settle open design choices in the brief. Brief it with clear scope and acceptance criteria, plus worker's report and evidence for a hand-back."
model: claude-sonnet-5-5
effort: medium
maxTurns: 100
disallowedTools: Agent, WebSearch, WebFetch, Artifact
skills:
    - acus
---

You own the delegated implementation. Use the parent's evidence first, inspect the minimum additional context, and follow repository instructions and established patterns. Every tool call costs one of your limited turns: put independent lookups into one `acus run` or several tool calls in the same response, and edit with one `acus patch` per change set.

Make the smallest cohesive change that meets the acceptance criteria and preserves existing user work. Include code, configuration, documentation, and regression tests when they belong to the task. Continue authorized work through the relevant verification without stopping for routine check-ins.

Run checks that directly validate the changed behavior and inspect their results before reporting success. A syntax-only check, or a check that failed to start, does not count. Repeat a passed check only after a relevant change or new evidence. Leave broad exploration, external research, and full test suites to the parent or the corresponding role unless explicitly delegated. Perform browser or accessibility checks only when included in scope.

Do not make unrelated refactors, start additional review rounds, delegate further, commit, push, release, or write to external services. If a material product decision, missing authority, destructive action, or scope expansion is required, stop and report the specific blocker.

Return the outcome, files changed, verification commands and results, remaining risks, and concrete follow-up. Label anything unverified instead of implying it passed.
"##;

fn worker(source: &str) -> String {
    derive(source, "worker", "deepseek-flash", Effort::Keep).unwrap()
}

#[test]
fn an_explicit_effort_replaces_the_source_effort() {
    let derived = derive(
        SENIOR_WORKER,
        "senior-worker",
        "deepseek-flash",
        Effort::High,
    )
    .unwrap();
    assert!(derived.lines().any(|line| line == "effort: high"));
    assert!(!derived.lines().any(|line| line == "effort: medium"));
}

#[test]
fn max_effort_is_written_to_the_derived_agent() {
    let derived = derive(WORKER, "worker", "deepseek-flash", Effort::Max).unwrap();
    assert!(
        derived.lines().any(|line| line == "effort: max"),
        "{derived}"
    );
}

#[test]
fn an_explicit_effort_is_added_when_the_source_has_none() {
    let source = r"---
name: worker
model: claude-haiku-5-5
---
";
    let derived = derive(source, "worker", "deepseek-flash", Effort::Low).unwrap();
    assert!(
        derived.lines().any(|line| line == "effort: low"),
        "{derived}"
    );
}

#[test]
fn a_plain_description_gets_the_note_on_its_line() {
    let expected = format!(
        "---\n{MARKER}\nname: worker-ds\ndescription: Does work. {NOTE}\nmodel: deepseek-flash\n---\nBody line.\n"
    );
    assert_eq!(worker(WORKER), expected);
}

#[test]
fn a_multi_line_plain_description_gets_the_note_on_its_last_line() {
    let source = "---\nname: worker\ndescription: Does work\n  across two lines.\n---\n";
    let expected = format!(
        "---\n{MARKER}\nname: worker-ds\nmodel: deepseek-flash\ndescription: Does work\n  across two lines. {NOTE}\n---\n"
    );
    assert_eq!(worker(source), expected);
}

#[test]
fn a_single_quoted_description_gets_the_note_before_the_closing_quote() {
    let source = "---\nname: worker\ndescription: 'It''s work.'\nmodel: x\n---\n";
    let expected = format!(
        "---\n{MARKER}\nname: worker-ds\ndescription: 'It''s work. {NOTE}'\nmodel: deepseek-flash\n---\n"
    );
    assert_eq!(worker(source), expected);
}

#[test]
fn a_double_quoted_description_gets_the_note_before_the_closing_quote() {
    let source = "---\nname: worker\ndescription: \"Does work.\"\nmodel: x\n---\n";
    let expected = format!(
        "---\n{MARKER}\nname: worker-ds\ndescription: \"Does work. {NOTE}\"\nmodel: deepseek-flash\n---\n"
    );
    assert_eq!(worker(source), expected);
}

#[test]
fn a_literal_block_description_gets_a_line_with_the_block_indent() {
    let source =
        "---\nname: worker\ndescription: |\n  First line.\n  Second line.\nmodel: x\n---\nBody\n";
    let expected = format!(
        "---\n{MARKER}\nname: worker-ds\ndescription: |\n  First line.\n  Second line.\n  {NOTE}\nmodel: deepseek-flash\n---\nBody\n"
    );
    assert_eq!(worker(source), expected);
}

#[test]
fn a_folded_block_description_keeps_the_blank_line_after_it() {
    let source = "---\nname: worker\ndescription: >-\n    Folded text.\n\nmodel: x\n---\n";
    let expected = format!(
        "---\n{MARKER}\nname: worker-ds\ndescription: >-\n    Folded text.\n    {NOTE}\n\nmodel: deepseek-flash\n---\n"
    );
    assert_eq!(worker(source), expected);
}

#[test]
fn a_missing_description_is_added_before_the_closing_fence() {
    let source = "---\nname: worker\nmodel: x\n---\nBody\n";
    let expected = format!(
        "---\n{MARKER}\nname: worker-ds\nmodel: deepseek-flash\ndescription: {NOTE}\n---\nBody\n"
    );
    assert_eq!(worker(source), expected);
}

#[test]
fn a_missing_model_is_inserted_after_name() {
    let source = "---\nname: worker\ndescription: Does work.\n---\n";
    let expected = format!(
        "---\n{MARKER}\nname: worker-ds\nmodel: deepseek-flash\ndescription: Does work. {NOTE}\n---\n"
    );
    assert_eq!(worker(source), expected);
}

#[test]
fn an_existing_model_is_replaced_with_its_continuation_lines() {
    let source = "---\nname: worker\nmodel: old-model\n  extra: continues\ndescription: x\n---\n";
    let expected = format!(
        "---\n{MARKER}\nname: worker-ds\nmodel: deepseek-flash\ndescription: x {NOTE}\n---\n"
    );
    assert_eq!(worker(source), expected);
}

#[test]
fn a_missing_name_is_added_as_the_first_key() {
    let source = "---\ndescription: x\nmodel: y\n---\n";
    let expected = format!(
        "---\n{MARKER}\nname: worker-ds\ndescription: x {NOTE}\nmodel: deepseek-flash\n---\n"
    );
    assert_eq!(worker(source), expected);
}

#[test]
fn a_comment_after_a_plain_description_stays_after_the_note() {
    let source = "---\nname: worker\ndescription: Does work. # for the lead\nmodel: x\n---\n";
    let expected = format!(
        "---\n{MARKER}\nname: worker-ds\ndescription: Does work. {NOTE} # for the lead\nmodel: deepseek-flash\n---\n"
    );
    assert_eq!(worker(source), expected);
}

#[test]
fn crlf_line_endings_are_kept() {
    let source = WORKER.replace('\n', "\r\n");
    assert_eq!(worker(&source), worker(WORKER).replace('\n', "\r\n"));
}

#[test]
fn the_body_is_kept_byte_for_byte() {
    let body = "# Title\n\n  indented   \n---\nmore\n";
    let source = format!("---\nname: worker\ndescription: x\n---\n{body}");
    assert!(worker(&source).ends_with(body));
}

#[test]
fn a_file_without_an_opening_fence_is_refused() {
    assert_eq!(
        derive(
            "name: worker\n---\n",
            "worker",
            "deepseek-flash",
            Effort::Keep
        ),
        Err(DeriveError::NoOpeningFence)
    );
}

#[test]
fn a_file_without_a_closing_fence_is_refused() {
    assert_eq!(
        derive(
            "---\nname: worker\n",
            "worker",
            "deepseek-flash",
            Effort::Keep
        ),
        Err(DeriveError::NoClosingFence)
    );
}

#[test]
fn a_derived_file_is_refused_as_a_source() {
    assert_eq!(
        derive(&worker(WORKER), "worker", "deepseek-flash", Effort::Keep),
        Err(DeriveError::AlreadyDerived)
    );
}

#[test]
fn an_unterminated_quoted_description_is_refused() {
    let source = "---\nname: worker\ndescription: \"Does work.\nmodel: x\n---\n";
    assert_eq!(
        derive(source, "worker", "deepseek-flash", Effort::Keep),
        Err(DeriveError::Description(
            "the quoted description is not closed"
        ))
    );
}

#[test]
fn the_senior_worker_fixture_derives_as_expected() {
    let expected = SENIOR_WORKER
        .replacen("---\n", &format!("---\n{SENIOR_MARKER}\n"), 1)
        .replacen("name: senior-worker\n", "name: senior-worker-ds\n", 1)
        .replacen(
            "for a hand-back.\"",
            "for a hand-back. DeepSeek variant of senior-worker on deepseek-flash, billed to the DeepSeek API credit.\"",
            1,
        )
        .replacen("model: claude-sonnet-5-5", "model: deepseek-flash", 1);
    assert_eq!(
        derive(
            SENIOR_WORKER,
            "senior-worker",
            "deepseek-flash",
            Effort::Keep
        )
        .unwrap(),
        expected
    );
}

#[test]
fn only_a_marker_in_the_frontmatter_makes_a_file_derived() {
    assert!(is_derived(&worker(WORKER)));
    assert!(!is_derived(WORKER));
    let body_only = format!("---\nname: x\n---\n{MARKER}\n");
    assert!(!is_derived(&body_only));
}

fn agent(from: &str) -> Agent {
    Agent {
        from: from.to_owned(),
        model: "deepseek-flash".to_owned(),
        effort: Effort::Keep,
        suspended: false,
    }
}

fn entry(agent: &str, file: &str, outcome: Outcome) -> Entry {
    Entry {
        agent: agent.to_owned(),
        file: file.to_owned(),
        outcome,
    }
}

fn file_names(dir: &Path) -> Vec<String> {
    let mut names: Vec<String> = fs::read_dir(dir)
        .unwrap()
        .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    names.sort();
    names
}

#[test]
fn a_written_file_is_unchanged_until_its_source_changes() {
    let dir = tempfile::tempdir().unwrap();
    fs::write(dir.path().join("worker.md"), WORKER).unwrap();
    let agents = [agent("worker")];
    let first = sync(dir.path(), &agents, true);
    assert_eq!(
        first.entries,
        [entry("worker", "worker-ds.md", Outcome::Written)]
    );
    let second = sync(dir.path(), &agents, true);
    assert_eq!(
        second.entries,
        [entry("worker", "worker-ds.md", Outcome::Unchanged)]
    );

    let changed = WORKER.replace("Does work.", "Does more work.");
    fs::write(dir.path().join("worker.md"), &changed).unwrap();
    let third = sync(dir.path(), &agents, true);
    assert_eq!(
        third.entries,
        [entry("worker", "worker-ds.md", Outcome::Written)]
    );
    let written = fs::read_to_string(dir.path().join("worker-ds.md")).unwrap();
    assert_eq!(written, worker(&changed));
}

#[test]
fn a_hand_written_target_is_a_conflict_and_stays_untouched() {
    let dir = tempfile::tempdir().unwrap();
    fs::write(dir.path().join("worker.md"), WORKER).unwrap();
    fs::write(dir.path().join("worker-ds.md"), "mine\n").unwrap();
    let report = sync(dir.path(), &[agent("worker")], true);
    assert_eq!(
        report.entries,
        [entry("worker", "worker-ds.md", Outcome::Conflict)]
    );
    let kept = fs::read_to_string(dir.path().join("worker-ds.md")).unwrap();
    assert_eq!(kept, "mine\n");
}

#[test]
fn unavailable_removes_only_the_derived_files() {
    let dir = tempfile::tempdir().unwrap();
    fs::write(dir.path().join("worker.md"), WORKER).unwrap();
    fs::write(dir.path().join("reviewer-ds.md"), "mine\n").unwrap();
    sync(dir.path(), &[agent("worker")], true);
    let report = sync(dir.path(), &[agent("worker")], false);
    assert_eq!(
        report.entries,
        [entry("worker", "worker-ds.md", Outcome::Removed)]
    );
    assert_eq!(file_names(dir.path()), ["reviewer-ds.md", "worker.md"]);
}

#[test]
fn derived_files_of_unconfigured_agents_are_removed() {
    let dir = tempfile::tempdir().unwrap();
    fs::write(dir.path().join("worker.md"), WORKER).unwrap();
    fs::write(dir.path().join("old.md"), WORKER).unwrap();
    sync(dir.path(), &[agent("old")], true);
    let report = sync(dir.path(), &[agent("worker")], true);
    assert_eq!(
        report.entries,
        [
            entry("worker", "worker-ds.md", Outcome::Written),
            entry("old", "old-ds.md", Outcome::Removed),
        ]
    );
    assert_eq!(
        file_names(dir.path()),
        ["old.md", "worker-ds.md", "worker.md"]
    );
}

#[test]
fn a_suspended_agent_is_withdrawn_and_its_source_stays() {
    let dir = tempfile::tempdir().unwrap();
    fs::write(dir.path().join("worker.md"), WORKER).unwrap();
    let mut agents = [agent("worker")];
    sync(dir.path(), &agents, true);
    agents[0].suspended = true;
    let report = sync(dir.path(), &agents, true);
    assert_eq!(
        report.entries,
        [entry("worker", "worker-ds.md", Outcome::Removed)]
    );
    assert_eq!(file_names(dir.path()), ["worker.md"]);
}

#[test]
fn a_missing_source_is_reported_and_creates_no_directory() {
    let dir = tempfile::tempdir().unwrap();
    let agents_dir = dir.path().join("agents");
    let report = sync(&agents_dir, &[agent("worker")], true);
    assert_eq!(
        report.entries,
        [entry("worker", "worker-ds.md", Outcome::SourceMissing)]
    );
    assert!(!agents_dir.exists());
}

#[test]
fn a_derived_file_whose_source_is_gone_is_removed() {
    let dir = tempfile::tempdir().unwrap();
    fs::write(dir.path().join("worker.md"), WORKER).unwrap();
    sync(dir.path(), &[agent("worker")], true);
    fs::remove_file(dir.path().join("worker.md")).unwrap();
    let report = sync(dir.path(), &[agent("worker")], true);
    assert_eq!(
        report.entries,
        [entry("worker", "worker-ds.md", Outcome::Removed)]
    );
    assert!(file_names(dir.path()).is_empty());
}

#[test]
fn a_hand_written_target_without_a_source_stays() {
    let dir = tempfile::tempdir().unwrap();
    fs::write(dir.path().join("worker-ds.md"), WORKER).unwrap();
    let report = sync(dir.path(), &[agent("worker")], true);
    assert_eq!(
        report.entries,
        [entry("worker", "worker-ds.md", Outcome::SourceMissing)]
    );
    assert_eq!(file_names(dir.path()), ["worker-ds.md"]);
}

#[test]
fn an_unparsable_source_is_reported_with_its_error() {
    let dir = tempfile::tempdir().unwrap();
    fs::write(dir.path().join("worker.md"), "no frontmatter\n").unwrap();
    let report = sync(dir.path(), &[agent("worker")], true);
    assert_eq!(
        report.entries,
        [entry(
            "worker",
            "worker-ds.md",
            Outcome::Unparsable(DeriveError::NoOpeningFence.to_string())
        )]
    );
}

#[test]
fn no_temporary_file_is_left_behind() {
    let dir = tempfile::tempdir().unwrap();
    fs::write(dir.path().join("worker.md"), WORKER).unwrap();
    sync(dir.path(), &[agent("worker")], true);
    assert_eq!(file_names(dir.path()), ["worker-ds.md", "worker.md"]);
}
